## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;                     // 125 MHz clock
  localparam logic [15:0] PRESCALE = 16'd5;          // Prescale value

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Reset generation
  // ------------------------------------------------------------
  logic rst = 0;
  initial begin
    // Initial reset pulse
    rst = 0;  #200;
    rst = 1;  #200;
    rst = 0;  #200;
  end

  // ------------------------------------------------------------
  // UART interface signals
  // ------------------------------------------------------------
  // AXI‑Stream output side
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;
  // Status side
  logic       busy;
  logic       overrun_error;
  logic       frame_error;
  // UART pin
  logic       rxd = 1'b1;

  // Tie‑off unused AXI‑Stream input signals (not used by uart_rx)
  logic [7:0] s_axis_tdata = '0;
  logic       s_axis_tvalid = 1'b0;
  logic       s_axis_tready = 1'b1;

  // ------------------------------------------------------------
  // DUT instantiation
  // ------------------------------------------------------------
  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd          (rxd),
    .busy         (busy),
    .overrun_error(overrun_error),
    .frame_error  (frame_error),
    .prescale     (PRESCALE)
  );

  // ------------------------------------------------------------
  // Helper functions / tasks
  // ------------------------------------------------------------
  function int bit_clks(input int p);
    return p * 8;
  endfunction

  // Send a UART frame on rxd.
  //   data   – byte to transmit (LSB first)
  //   stop_low – 1 → stop bit forced low (causes frame_error)
  task automatic uart_send_frame(input byte unsigned data, input logic stop_low);
    int bc;
    bc = bit_clks(int'(PRESCALE));

    // Start bit
    rxd = 0;
    repeat (bc) @(negedge clk);

    // Data bits, LSB first
    for (int i = 0; i < 8; i = i + 1) begin
      rxd = data[i];
      repeat (bc) @(negedge clk);
    end

    // Stop bit
    rxd = stop_low ? 0 : 1;
    repeat (bc) @(negedge clk);
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // ----------------------------------------------------------------
    // Wait until reset is released
    // ----------------------------------------------------------------
    @(negedge rst);

    // ----------------------------------------------------------------
    // First frame: send 0x3C with a high stop bit (no error)
    // ----------------------------------------------------------------
    @(posedge clk);
    uart_send_frame(8'h3C, 1'b1);               // stop bit = 1 (normal)

    // Keep back‑pressure asserted (m_axis_tready stays 0)
    repeat (100) @(negedge clk);               // let DUT load the word

    // ----------------------------------------------------------------
    // Second frame: send a frame that ends with a low stop bit → frame_error
    // ----------------------------------------------------------------
    @(posedge clk);
    uart_send_frame(8'hAA, 1'b0);               // stop bit = 0 → frame_error

    // Wait long enough for the cover property to be evaluated
    repeat (200) @(negedge clk);

    // ----------------------------------------------------------------
    // Target coverage point observed – finish simulation
    // ----------------------------------------------------------------
    $display("R19 coverage point observed – simulation ending.");
    $finish;
  end

endmodule
```

